// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.workerimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport com.roshan.persona.automation.model.AutomationRuleimport com.roshan.persona.automation.model.AutomationTriggerimport com.roshan.persona.automation.scheduler.AutomationSchedulerimport dagger.hilt.EntryPointimport dagger.hilt.InstallInimport dagger.hilt.android.EntryPointAccessorsimport dagger.hilt.components.SingletonComponentimport timber.log.Timber/** * NOUS — Automation Event Receiver (Module 8). * * REAL [BroadcastReceiver] that listens for system events and forwards * them to [AutomationWorker] for any matching [AutomationTrigger.EventTrigger] * rules. * * ## Why a manifest-registered receiver? * * The dynamic receivers registered by [AutomationScheduler] for individual * [EventTrigger] rules work while the app process is alive. But for events * that need to fire even when the app is dead (e.g., `BOOT_COMPLETED`, * `SCREEN_ON`, `SCREEN_OFF`), we need a manifest-registered receiver. * * This receiver is a fallback: it queries the [com.roshan.persona.automation.engine.AutomationEngine] * for any rules whose [EventTrigger.eventType] matches the received action, * and enqueues a fire for each. * * ## What the receiver does * *   1. Map the incoming intent action to an [com.roshan.persona.automation.model.EventType]. *   2. Get the singleton [com.roshan.persona.automation.engine.AutomationEngine]. *   3. Iterate all enabled rules; for each rule with an [EventTrigger] of *      the matching type, enqueue a fire via [AutomationScheduler.enqueueOneShotFire]. * * ## Permissions * * Some events require permissions (e.g., `RECEIVE_SMS` for SMS_RECEIVED, * `READ_PHONE_STATE` for PHONE_STATE). The receiver is declared in the * manifest with the necessary intent-filters, but the runtime permissions * are requested by the UI when the user creates an automation rule with * that event type. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */class AutomationEventReceiver : BroadcastReceiver() {    companion object {        private const val TAG = "AutomationEventReceiver"    }    override fun onReceive(context: Context, intent: Intent) {        val action = intent.action ?: return        val eventType = actionToEventType(action) ?: run {            Timber.tag(TAG).d("Unknown action: %s — ignoring.", action)            return        }        Timber.tag(TAG).i("Event received: %s (action=%s)", eventType, action)        val entryPoint = EntryPointAccessors.fromApplication(            context.applicationContext,            EventReceiverEntryPoint::class.java,        )        val engine = entryPoint.automationEngine()        val scheduler = entryPoint.scheduler()        val rules = engine.listRules()        var matched = 0        for (rule in rules) {            if (!rule.isEnabled) continue            val trigger = rule.trigger            if (trigger !is AutomationTrigger.EventTrigger) continue            if (trigger.eventType != eventType) continue            // Package filter (if set).            if (trigger.packageName != null) {                val pkg = intent.`package` ?: ""                if (pkg != trigger.packageName) continue            }            Timber.tag(TAG).i("Event matched rule '%s' (id=%s) — enqueuing fire.", rule.name, rule.id)            scheduler.enqueueOneShotFire(rule.id, AutomationWorker.TRIGGER_KIND_EVENT)            matched++        }        if (matched == 0) {            Timber.tag(TAG).d("No rules matched event %s.", eventType)        }    }    /**     * Map a system broadcast action to an [com.roshan.persona.automation.model.EventType].     *     * Returns `null` for actions this receiver doesn't handle.     */    private fun actionToEventType(action: String): com.roshan.persona.automation.model.EventType? {        return when (action) {            Intent.ACTION_SCREEN_ON -> com.roshan.persona.automation.model.EventType.SCREEN_ON            Intent.ACTION_SCREEN_OFF -> com.roshan.persona.automation.model.EventType.SCREEN_OFF            Intent.ACTION_USER_PRESENT -> com.roshan.persona.automation.model.EventType.USER_PRESENT            Intent.ACTION_BOOT_COMPLETED -> com.roshan.persona.automation.model.EventType.BOOT_COMPLETED            "android.provider.Telephony.SMS_RECEIVED" -> com.roshan.persona.automation.model.EventType.SMS_RECEIVED            "android.intent.action.PHONE_STATE" -> com.roshan.persona.automation.model.EventType.CALL_INCOMING            else -> null        }    }}/** * Hilt entry point for accessing [com.roshan.persona.automation.engine.AutomationEngine] * + [AutomationScheduler] from the event receiver. */@EntryPoint@InstallIn(SingletonComponent::class)interface EventReceiverEntryPoint {    /** Access the singleton [com.roshan.persona.automation.engine.AutomationEngine]. */    fun automationEngine(): com.roshan.persona.automation.engine.AutomationEngine    /** Access the singleton [AutomationScheduler]. */    fun scheduler(): AutomationScheduler}/** * Internal helper — check if a rule's trigger matches the given action. * * Used by tests + the receiver's filtering logic. */@Suppress("unused")internal fun ruleMatchesEventAction(rule: AutomationRule, action: String): Boolean {    val trigger = rule.trigger as? AutomationTrigger.EventTrigger ?: return false    val eventType = when (action) {        Intent.ACTION_SCREEN_ON -> com.roshan.persona.automation.model.EventType.SCREEN_ON        Intent.ACTION_SCREEN_OFF -> com.roshan.persona.automation.model.EventType.SCREEN_OFF        Intent.ACTION_USER_PRESENT -> com.roshan.persona.automation.model.EventType.USER_PRESENT        Intent.ACTION_BOOT_COMPLETED -> com.roshan.persona.automation.model.EventType.BOOT_COMPLETED        "android.provider.Telephony.SMS_RECEIVED" -> com.roshan.persona.automation.model.EventType.SMS_RECEIVED        "android.intent.action.PHONE_STATE" -> com.roshan.persona.automation.model.EventType.CALL_INCOMING        else -> return false    }    return trigger.eventType == eventType}